CREATE TABLE vis_lock (lock_key VARCHAR(255) PRIMARY KEY);
CREATE TABLE vis_challenge (id VARCHAR(36) PRIMARY KEY,subject_id VARCHAR(120) NOT NULL,store_id VARCHAR(120) NOT NULL,expires_at BIGINT NOT NULL,used BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE vis_visit (id VARCHAR(36) PRIMARY KEY,subject_id VARCHAR(120) NOT NULL,store_id VARCHAR(120) NOT NULL,merchant_id VARCHAR(120) NOT NULL,entered_at BIGINT NOT NULL,left_at BIGINT NULL,source VARCHAR(16) NOT NULL,actor_id VARCHAR(120) NOT NULL,reason VARCHAR(120),consumption_id VARCHAR(120) NOT NULL,version BIGINT NOT NULL DEFAULT 0, active_subject VARCHAR(120) GENERATED ALWAYS AS (IF(left_at IS NULL,subject_id,NULL)) STORED,UNIQUE KEY one_present(store_id,active_subject));
CREATE TABLE rnk_receipt(actor_id VARCHAR(120) NOT NULL,idem_key VARCHAR(120) NOT NULL,body VARCHAR(1500) NOT NULL,resource_id VARCHAR(36) NOT NULL,PRIMARY KEY(actor_id,idem_key));
CREATE TABLE rnk_outbox(event_id VARCHAR(36) PRIMARY KEY,type VARCHAR(64) NOT NULL,schema_version INT NOT NULL,producer VARCHAR(32) NOT NULL,aggregate_id VARCHAR(36) NOT NULL,aggregate_version BIGINT NOT NULL,occurred_at BIGINT NOT NULL,merchant_id VARCHAR(120),store_id VARCHAR(120),mode VARCHAR(16) NOT NULL,payload JSON NOT NULL);
CREATE TABLE rnk_raw(event_id VARCHAR(120) PRIMARY KEY,subject_id VARCHAR(120) NOT NULL,source VARCHAR(32) NOT NULL,scope_key VARCHAR(140) NOT NULL,body VARCHAR(1500) NOT NULL,qualification VARCHAR(32) NOT NULL,started_at BIGINT NOT NULL,ended_at BIGINT NOT NULL);
CREATE TABLE rnk_day(subject_id VARCHAR(120) NOT NULL,scope_key VARCHAR(140) NOT NULL,valid_date DATE NOT NULL,PRIMARY KEY(subject_id,scope_key,valid_date));
CREATE TABLE rnk_participant(subject_id VARCHAR(120) NOT NULL,scope_key VARCHAR(140) NOT NULL,enabled BOOLEAN NOT NULL DEFAULT FALSE,nickname VARCHAR(120) NOT NULL,version BIGINT NOT NULL DEFAULT 0,PRIMARY KEY(subject_id,scope_key));
CREATE TABLE rnk_appeal(id VARCHAR(36) PRIMARY KEY,event_id VARCHAR(120) NOT NULL,subject_id VARCHAR(120) NOT NULL,reason VARCHAR(120) NOT NULL,state VARCHAR(24) NOT NULL DEFAULT 'PENDING_REVIEW',created_at BIGINT NOT NULL);
